<?php declare(strict_types=1);require_once __DIR__.'/includes/bootstrap.php';require_user();$title='KYC';$rows=dball('SELECT * FROM kyc_documents WHERE user_id=? ORDER BY id DESC',[user_id()]);if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();dbq('INSERT INTO kyc_documents(user_id,document_type,document_number,status) VALUES(?,?,?,?)',[user_id(),post('document_type'),post('document_number'),'pending']);flash('success','KYC document submitted for review.');redirect('index.php?page=kyc');}require __DIR__.'/includes/header.php';?><div class="grid-2"><div class="card"><h1>Submit KYC</h1><form method="post"><?=csrf_field()?><div class="field"><label>Document type</label><select name="document_type"><option>Passport</option><option>National ID</option><option>Driver License</option></select></div><div class="field"><label>Document number</label><input name="document_number" required></div><br><button class="btn">Submit</button></form></div><div class="card"><h2>Submissions</h2><?php foreach($rows as $r):?><p><b><?=e($r['document_type'])?></b> · <?=e($r['document_number'])?> · <span class="badge"><?=e($r['status'])?></span></p><?php endforeach;?></div></div><?php require __DIR__.'/includes/footer.php';?>